/* eslint-disable no-unused-vars */
import React, { useEffect, useState, Suspense, useContext } from 'react';

import { __ } from '@wordpress/i18n';
import {
	TextControl,
	Button,
	ButtonGroup,
	RadioControl,
	SelectControl,
	ToggleControl,
} from '@wordpress/components';
import { useAsyncResource } from 'use-async-resource';
import { useForm, Controller, useWatch, useFormState } from 'react-hook-form';
import classNames from 'classnames';
import GearIcon from '../../components/icons/Gear';
import sendCommand from '../../utils/SendCommand';
import Notice from '../admin-components/Notice';
import { Fancybox } from '@fancyapps/ui/src/Fancybox/Fancybox.js';
import '@fancyapps/ui/dist/fancybox.css';
import AdminDefaultsLoader from '../admin-components/Loaders/AdminDefaultsLoader';
import CircularExclamationIcon from '../../components/icons/CircularExplanation';
import twttr from '../../validation/twitter';
import CircularInfo from '../../components/icons/CircularInfo';
import FlaskIcon from '../../components/icons/FlaskIcon';
import TabsContext from '../contexts/TabsContext';
import Spinner from '../../components/icons/Spinner';
import fontFamilies from '../../../fonts/fonts';

const retrieveDefaults = () => {
	return sendCommand( 'quotes_dlx_retrieve_admin_options_defaults', {
		nonce: quotes_dlx_admin.options_retrieve_nonce,
	} );
};

const AdminAdvanced = ( props ) => {
	const [ defaults, getDefaults ] = useAsyncResource( retrieveDefaults, [] );

	return (
		<Suspense fallback={ <AdminDefaultsLoader /> }>
			<Interface defaults={ defaults } { ...props } />
		</Suspense>
	);
};

const Interface = ( props ) => {
	const localStorageKey = 'quotes_dlx_form_advanced';

	const { advancedTabDirtyCount, setAdvancedTabDirtyCount } = useContext( TabsContext );
	const { defaults } = props;
	const response = defaults();
	const { data, success } = response.data;

	const [ showButtonOptions, setShowButtonOptions ] = useState(
		data.tweet_button_enabled
	);
	const [ buttonDisplay, setButtonDisplay ] = useState( data.tweet_button_display );
	const [ anchorDisplay, setAnchorDisplay ] = useState( data.has_anchor );
	const [ enableLinks, setEnableLinks ] = useState( data.enable_links_in_tweet );
	const [ enableUrlShortener, setEnableUrlShortener ] = useState(
		data.url_shortener
	);
	const [ loading, setLoading ] = useState( true );
	const [ saving, setSaving ] = useState( false );
	const [ isSaved, setIsSaved ] = useState( false );
	const [ resetting, setResetting ] = useState( false );
	const [ isReset, setIsReset ] = useState( false );

	const {
		desktop_breakpoint,
		desktop_breakpoint_unit,
		tablet_breakpoint,
		tablet_breakpoint_unit,
		mobile_breakpoint,
		mobile_breakpoint_unit,
		enable_fonts,
		custom_font_primary,
		custom_font_secondary,
		enable_custom_fonts,
		primary_font_family,
		secondary_font_family,
		enable_adobe_fonts,
		adobe_project_id,
		adobe_fonts,
		template,
	} = data;

	const { register, control, handleSubmit, setValue, getValues, reset } =
		useForm( {
			defaultValues: {
				desktopBreakpoint: desktop_breakpoint,
				desktopBreakpointUnit: desktop_breakpoint_unit,
				tabletBreakpoint: tablet_breakpoint,
				tabletBreakpointUnit: tablet_breakpoint_unit,
				mobileBreakpoint: mobile_breakpoint,
				mobileBreakpointUnit: mobile_breakpoint_unit,
				enableFonts: enable_fonts,
				enableCustomFonts: enable_custom_fonts,
				customFontPrimary: custom_font_primary,
				customFontSecondary: custom_font_secondary,
				primaryFontFamily: primary_font_family,
				secondaryFontFamily: secondary_font_family,
				enableAdobeFonts: enable_adobe_fonts,
				adobeProjectId: adobe_project_id,
			},
		} );

	const formValues = useWatch( { control } );

	const { errors, isDirty, dirtyFields, touchedFields } = useFormState( {
		control,
	} );

	const onSubmit = ( formData ) => {
		setSaving( true );

		// Populate possible empty hashtags.
		if ( formData.hashtags.length === 0 ) {
			formData.hashtags = null;
		}
		sendCommand( 'quotes_dlx_save_admin_options_defaults', {
			nonce: quotes_dlx_admin.options_save_nonce,
			form_data: formData,
		} )
			.then( ( ajaxResponse ) => {
				const ajaxData = ajaxResponse.data.data;
				const ajaxSuccess = ajaxResponse.data.success;
				if ( ajaxSuccess ) {
					// Reset count.
					setAdvancedTabDirtyCount( 0 );

					// Clear form dirty.
					reset( ajaxData );
					localStorage.removeItem( localStorageKey );

					setIsSaved( true );
					setTimeout( () => {
						setIsSaved( false );
					}, 3000 );
				} else {
					// Error stuff.
				}
			} )
			.catch( ( ajaxResponse ) => {} )
			.then( ( ajaxResponse ) => {
				setSaving( false );
			} );
	};

	const handleReset = ( e ) => {
		setResetting( true );
		sendCommand( 'quotes_dlx_reset_admin_options_defaults', {
			nonce: quotes_dlx_admin.options_save_nonce,
		} )
			.then( ( ajaxResponse ) => {
				const ajaxData = ajaxResponse.data.data;
				const ajaxSuccess = ajaxResponse.data.success;
				if ( ajaxSuccess ) {
					// Reset local storage.
					setAdvancedTabDirtyCount( 0 );

					// Clear form dirty.
					reset( ajaxData );
					localStorage.removeItem( localStorageKey );

					// Reset toggles.
					setShowButtonOptions( ajaxData.tweetButtonEnabled );
					setEnableLinks( ajaxData.enableLinksInTweet );
					setEnableUrlShortener( ajaxData.urlShortener );
					setAnchorDisplay( ajaxData.hasAnchor );
					setButtonDisplay( ajaxData.tweetButtonDisplay );

					setIsReset( true );
					setTimeout( () => {
						setIsReset( false );
					}, 3000 );
				} else {
					// Error stuff.
				}
			} )
			.catch( ( ajaxResponse ) => {} )
			.then( ( ajaxResponse ) => {
				setResetting( false );
			} );
	};

	const hasErrors = () => {
		return Object.keys( errors ).length > 0;
	};

	useEffect( () => {
		console.log( advancedTabDirtyCount );
		const maybeSavedFormFields = localStorage.getItem( localStorageKey );
		if ( null !== maybeSavedFormFields ) {
			const valuesToSave = JSON.parse( maybeSavedFormFields );
			for ( const [ key, value ] of Object.entries( valuesToSave ) ) {
				setValue( key, value, { shouldDirty: true, shouldValidate: true } );
			}
		}
		if ( isDirty ) {
			const touchedFieldsCountToSave = Object.keys( dirtyFields ).length;
			setAdvancedTabDirtyCount( touchedFieldsCountToSave );
		}
		setLoading( false );
	}, [] );

	useEffect( () => {
		if ( saving || resetting || loading ) {
			return;
		}
		if ( isDirty || advancedTabDirtyCount > 0 ) {
			// Get current form values.
			const formValuesToSave = JSON.stringify( getValues() );

			// Get the length of the fields that need to be saved.
			const touchedFieldsCountToSave = Object.keys( dirtyFields ).length;

			setAdvancedTabDirtyCount( touchedFieldsCountToSave );

			// Store touched fields.
			localStorage.setItem( localStorageKey, formValuesToSave );
		} else {
			setAdvancedTabDirtyCount( 0 );
		}
		setLoading( false );
	}, [ formValues ] );

	// Get URL Shortening services (i.e., bitly, jetpack).
	const linkShortenerServices = [];
	if ( quotes_dlx_admin.bitly_plugin_active ) {
		linkShortenerServices.push( {
			label: __( 'Bitly', 'quotes-dlx' ),
			value: 'bitly',
		} );
	}
	if ( quotes_dlx_admin.jetpack_plugin_active ) {
		linkShortenerServices.push( {
			label: __( 'Jetpack', 'quotes-dlx' ),
			value: 'jetpack',
		} );
	}

	if ( loading ) {
		return <AdminDefaultsLoader />;
	}

	const getFontFamilies = () => {
		// Get font families in value label pair.
		const families = [];
		for ( const [ key, fontfamily ] of Object.entries( fontFamilies ) ) {
			families.push( {
				label: fontfamily.name,
				value: fontfamily.slug,
			} );
		}
		families.push(
			{
				label: __( 'Custom', 'quotes-dlx' ),
				value: 'custom',
			}
		);
		return families;
	};

	const toTitleCase = ( string ) => {
		const firstLetterRegex = /(^[a-z])/g;
		const newString = string.replace( firstLetterRegex, ( match ) => {
			return match.toUpperCase();
		} );
		return newString.replace( /-([a-z])/ig, function( all, letter ) {
			return ' ' + letter.toUpperCase();
		} );
	};

	const getPreviewLink = () => {
		return `${ ajaxurl }?action=quotes_dlx_theme_preview&fontsize=16
		) }&lineheight=${ encodeURIComponent(
		1.65
	) }&buttonsize=${ encodeURIComponent( 16 ) }&nonce=${
	quotes_dlx_admin.options_retrieve_nonce
}&template=${ encodeURIComponent( template ) }&screen=tablet&primary_font_family=${ encodeURIComponent(
	toTitleCase( getValues( 'primaryFontFamily' ) )
) }&secondary_font_family=${ encodeURIComponent(
	toTitleCase( getValues( 'secondaryFontFamily' ) )
) }`;
	};

	return (
		<>
			<div className="qdlx-admin__tabs--content-wrap">
				<form onSubmit={ handleSubmit( onSubmit ) }>
					<div className="qdlx-admin__tabs--content-panel">
						<div className="qdlx-admin__tabs--content-heading">
							<h1>
								<FlaskIcon width={ 48 } height={ 48 } aria-hidden="true" />
								<span className="qdlx-admin__heading--text">
									{ __( 'Advanced Options', 'quotes-dlx' ) }
								</span>
							</h1>
							<p className="description">
								{ __(
									'Advanced options allow you to set breakpoints and reset options.',
									'quotes-dlx'
								) }
							</p>
						</div>
						<div className="qdlx-admin__tabs--content-inner">
							<table className="form-table" role="presentation">
								<tbody>
									<tr>
										<th scope="row">{ __( 'Font Options', 'quotes-dlx' ) }</th>
										<td>
											<Controller
												name="enableFonts"
												control={ control }
												render={ ( { field: { onChange, value } } ) => (
													<ToggleControl
														label={ __(
															'Enable Theme Fonts',
															'quotes-dlx'
														) }
														className="qdlx-admin__toggle-control"
														checked={ value }
														onChange={ ( boolValue ) => {
															onChange( boolValue );
														} }
														help={ __(
															'By default, the themes load their own fonts. If you would like to supply your own fonts, you can disable this option.',
															'quotes-dlx'
														) }
													/>
												) }
											/>
											<Controller
												name="enableAdobeFonts"
												control={ control }
												render={ ( { field: { onChange, value } } ) => (
													<ToggleControl
														label={ __(
															'Enable Adobe Fonts',
															'quotes-dlx'
														) }
														className="qdlx-admin__toggle-control"
														checked={ value }
														onChange={ ( boolValue ) => {
															onChange( boolValue );
														} }
														help={ __(
															'If you are using Adobe Fonts, you can use them in QuotesDLX.',
															'quotes-dlx'
														) }
													/>
												) }
											/>
											{ getValues( 'enableAdobeFonts' ) && (
												<>
													<Controller
														name="adobeProjectId"
														control={ control }
														rules={ { required: true, pattern: /^[a-z0-9]+$/i } }
														render={ ( { field } ) => (
															<TextControl
																{ ...field }
																label={ __( 'Adobe Fonts Project ID', 'quotes-dlx' ) }
																className={ classNames(
																	'qdlx-admin__text-control',
																	{
																		'has-error':
																		'pattern' ===
																			errors.anchorPrefix?.type ||
																		'required' ===
																			errors.anchorPrefix?.type,
																		'is-required': true,
																	}
																) }
																aria-required="true"
																help={ __(
																	'Enter the Adobe Project ID of the web project in order to load Adobe Fonts.',
																	'quotes-dlx'
																) }
															/>
														) }
													/>
													{ 'required' === errors.adobeProjectId?.type && (
														<Notice
															message={ __(
																'This field is a required field.'
															) }
															status="error"
															politeness="assertive"
															inline={ true }
															icon={ CircularExclamationIcon }
														/>
													) }
													{ 'pattern' === errors.adobeProjectId?.type && (
														<Notice
															message={ __(
																'Please use only lowercase letters and numbers.'
															) }
															status="error"
															politeness="assertive"
															inline={ true }
															icon={ CircularExclamationIcon }
														/>
													) }
												</>
											) }
										</td>
									</tr>
									<tr>
										<th scope="row">{ __( 'Font Selection', 'quotes-dlx' ) }</th>
										<td>
											<div className="quotes-dlx-admin-theme-options__select span-2">
												<Controller
													name="primaryFontFamily"
													control={ control }
													render={ ( { field: { onChange, value } } ) => (
														<SelectControl
															className="qdlx-admin__themes--content-inner qdlx-admin__theme-fonts-select"
															label={ __( 'Select a Primary Font', 'quotes-dlx' ) }
															value={ value }
															onChange={ ( newFont ) => onChange( newFont ) }
															options={ getFontFamilies() }
														/>
													) }
												/>
												{ 'custom' === getValues( 'primaryFontFamily' ) && (
													<>
														<div className="quotes-dlx-admin-control-wrapper">
															<Controller
																name="customFontPrimary"
																control={ control }
																rules={ { required: true, pattern: /^[-\" ,A-Za-z0-9]+$/i } }
																render={ ( { field } ) => (
																	<TextControl
																		{ ...field }
																		label={ __( 'Enter your custom secondary font.', 'quotes-dlx' ) }
																		placeholder={ __( 'e.g. "Open Sans", sans-serif', 'quotes-dlx' ) }
																		className={ classNames( 'qdlx-admin__text-control', {
																			'has-error':
																	'pattern' === errors.customFontPrimary?.type ||
																	'required' === errors.customFontPrimary?.type,
																			'is-required': true,
																		} ) }
																		help={ __(
																			'Set the font and fallbacks.',
																			'quotes-dlx'
																		) }
																		aria-required="true"
																	/>
																) }
															/>
															{ 'required' === errors.customFontPrimary?.type && (
																<Notice
																	message={ __( 'This field is a required field.' ) }
																	status="error"
																	politeness="assertive"
																	inline={ true }
																	icon={ CircularExclamationIcon }
																/>
															) }
															{ 'pattern' === errors.customFontPrimary?.type && (
																<Notice
																	message={ __( 'There are invalid characters in the custom font. Make sure you are using double quotes instead of single quotes and leave out the semi-colon at the end.' ) }
																	status="error"
																	politeness="assertive"
																	inline={ true }
																	icon={ CircularExclamationIcon }
																/>
															) }
														</div>
													</>
												) }
											</div>
											<div className="quotes-dlx-admin-theme-options__select span-2">
												<Controller
													name="secondaryFontFamily"
													control={ control }
													render={ ( { field: { onChange, value } } ) => (
														<SelectControl
															className="qdlx-admin__themes--content-inner qdlx-admin__theme-fonts-select"
															label={ __( 'Select a Secondary Font', 'quotes-dlx' ) }
															value={ value }
															onChange={ ( newFont ) => onChange( newFont ) }
															options={ getFontFamilies() }
														/>
													) }
												/>
												{ 'custom' === getValues( 'secondaryFontFamily' ) && (
													<>
														<div className="quotes-dlx-admin-control-wrapper">
															<Controller
																name="customFontSecondary"
																control={ control }
																rules={ { required: true, pattern: /^[-\" ,A-Za-z0-9]+$/i } }
																render={ ( { field } ) => (
																	<TextControl
																		{ ...field }
																		label={ __( 'Enter your custom secondary font.', 'quotes-dlx' ) }
																		placeholder={ __( 'e.g. "Open Sans", sans-serif', 'quotes-dlx' ) }
																		className={ classNames( 'qdlx-admin__text-control', {
																			'has-error':
																	'pattern' === errors.customFontSecondary?.type ||
																	'required' === errors.customFontSecondary?.type,
																			'is-required': true,
																		} ) }
																		help={ __(
																			'Set the font and fallbacks.',
																			'quotes-dlx'
																		) }
																		aria-required="true"
																	/>
																) }
															/>
															{ 'required' === errors.customFontSecondary?.type && (
																<Notice
																	message={ __( 'This field is a required field.' ) }
																	status="error"
																	politeness="assertive"
																	inline={ true }
																	icon={ CircularExclamationIcon }
																/>
															) }
															{ 'pattern' === errors.customFontSecondary?.type && (
																<Notice
																	message={ __( 'There are invalid characters in the custom font. Make sure you are using double quotes instead of single quotes and leave out the semi-colon at the end.' ) }
																	status="error"
																	politeness="assertive"
																	inline={ true }
																	icon={ CircularExclamationIcon }
																/>
															) }
														</div>
													</>
												) }
											</div>
											<div className="components-base-control">
												<a
													data-fancybox
													onClick={ ( e ) => {
														e.preventDefault();
														new Fancybox(
															[
																{
																	src: getPreviewLink(),
																	type: 'iframe',
																},
															],
															{
																mainClass: 'qdlx-theme-preview-mobile',
																caption: __( 'Font Preview', 'quotes-dlx' ),
															}
														);
													} }
													href={ getPreviewLink() }
												>
													{ __( 'Preview Font', 'quotes-dlx' ) }
												</a>
											</div>
											{ getValues( 'enableFonts' ) && (
												<Controller
													name="enableCustomFonts"
													control={ control }
													render={ ( { field: { onChange, value } } ) => (
														<ToggleControl
															label={ __(
																'Enable Custom Fonts',
																'quotes-dlx'
															) }
															className="qdlx-admin__toggle-control"
															checked={ value }
															onChange={ ( boolValue ) => {
																onChange( boolValue );
															} }
															help={ __(
																'Enter your own font stack to use for the themes. If you would like to use the default fonts, you can disable this option.',
																'quotes-dlx'
															) }
														/>
													) }
												/>
											) }

										</td>
									</tr>
									<tr>
										<th scope="row">{ __( 'Breakpoints', 'quotes-dlx' ) }</th>
										<td>
											<div className="qdlx-admin__control-item">
												<Controller
													name="desktopBreakpoint"
													control={ control }
													rules={ { required: true, pattern: /^[0-9]+$/i } }
													render={ ( { field } ) => (
														<TextControl
															{ ...field }
															label={ __( 'Desktop Breakpoint', 'quotes-dlx' ) }
															className={ classNames( 'qdlx-admin__text-control', {
																'has-error':
																'pattern' === errors.desktopBreakpoint?.type ||
																'required' === errors.desktopBreakpoint?.type,
																'is-required': true,
															} ) }
															help={ __(
																'Set the desktop breakpoint for all themes.',
																'quotes-dlx'
															) }
															aria-required="true"
														/>
													) }
												/>
												{ 'required' === errors.desktopBreakpoint?.type && (
													<Notice
														message={ __( 'This field is a required field.' ) }
														status="error"
														politeness="assertive"
														inline={ true }
														icon={ CircularExclamationIcon }
													/>
												) }
												{ 'pattern' === errors.desktopBreakpoint?.type && (
													<Notice
														message={ __( 'The desktop breakpoint can only be numbers.' ) }
														status="error"
														politeness="assertive"
														inline={ true }
														icon={ CircularExclamationIcon }
													/>
												) }
												<Controller
													control={ control }
													name="desktopBreakpointUnit"
													render={ ( { field: { onChange, value } } ) => (
														<RadioControl
															label={ __( 'Desktop Breakpoint Unit', 'quotes-dlx' ) }
															help={ __(
																'Select a unit for the desktop breakpoint.',
																'quotes-dlx'
															) }
															selected={ value }
															onChange={ onChange }
															options={ [
																{ label: 'px', value: 'px' },
																{ label: 'em', value: 'em' },
															] }
														/>
													) }
												/></div>
											<div className="qdlx-admin__control-item">
												<Controller
													name="tabletBreakpoint"
													control={ control }
													rules={ { required: true, pattern: /^[0-9]+$/i } }
													render={ ( { field } ) => (
														<TextControl
															{ ...field }
															label={ __( 'Tablet Breakpoint', 'quotes-dlx' ) }
															className={ classNames( 'qdlx-admin__text-control', {
																'has-error':
																'pattern' === errors.tabletBreakpoint?.type ||
																'required' === errors.tabletBreakpoint?.type,
																'is-required': true,
															} ) }
															help={ __(
																'Set the tablet breakpoint for all themes.',
																'quotes-dlx'
															) }
															aria-required="true"
														/>
													) }
												/>
												{ 'required' === errors.tabletBreakpoint?.type && (
													<Notice
														message={ __( 'This field is a required field.' ) }
														status="error"
														politeness="assertive"
														inline={ true }
														icon={ CircularExclamationIcon }
													/>
												) }
												{ 'pattern' === errors.tabletBreakpoint?.type && (
													<Notice
														message={ __( 'The tablet breakpoint can only be numbers.' ) }
														status="error"
														politeness="assertive"
														inline={ true }
														icon={ CircularExclamationIcon }
													/>
												) }
												<Controller
													control={ control }
													name="tabletBreakpointUnit"
													render={ ( { field: { onChange, value } } ) => (
														<RadioControl
															label={ __( 'Tablet Breakpoint Unit', 'quotes-dlx' ) }
															help={ __(
																'Select a unit for the tablet breakpoint.',
																'quotes-dlx'
															) }
															selected={ value }
															onChange={ onChange }
															options={ [
																{ label: 'px', value: 'px' },
																{ label: 'em', value: 'em' },
															] }
														/>
													) }
												/>
											</div>
											<div className="qdlx-admin__control-item">
												<Controller
													name="mobileBreakpoint"
													control={ control }
													rules={ { required: true, pattern: /^[0-9]+$/i } }
													render={ ( { field } ) => (
														<TextControl
															{ ...field }
															label={ __( 'Mobile Breakpoint', 'quotes-dlx' ) }
															className={ classNames( 'qdlx-admin__text-control', {
																'has-error':
																'pattern' === errors.mobileBreakpoint?.type ||
																'required' === errors.mobileBreakpoint?.type,
																'is-required': true,
															} ) }
															help={ __(
																'Set the mobile breakpoint for all themes.',
																'quotes-dlx'
															) }
															aria-required="true"
														/>
													) }
												/>
												{ 'required' === errors.mobileBreakpoint?.type && (
													<Notice
														message={ __( 'This field is a required field.' ) }
														status="error"
														politeness="assertive"
														inline={ true }
														icon={ CircularExclamationIcon }
													/>
												) }
												{ 'pattern' === errors.mobileBreakpoint?.type && (
													<Notice
														message={ __( 'The mobile breakpoint can only be numbers.' ) }
														status="error"
														politeness="assertive"
														inline={ true }
														icon={ CircularExclamationIcon }
													/>
												) }
												<Controller
													control={ control }
													name="mobileBreakpointUnit"
													render={ ( { field: { onChange, value } } ) => (
														<RadioControl
															label={ __( 'Mobile Breakpoint Unit', 'quotes-dlx' ) }
															help={ __(
																'Select a unit for the mobile breakpoint.',
																'quotes-dlx'
															) }
															selected={ value }
															onChange={ onChange }
															options={ [
																{ label: 'px', value: 'px' },
																{ label: 'em', value: 'em' },
															] }
														/>
													) }
												/></div>
										</td>
									</tr>
								</tbody>
							</table>
							<div className="qdlx-admin__tabs--content-actions">
								<Button
									className={ classNames(
										'qdlx__btn qdlx__btn-primary qdlx__btn--icon-right',
										{ 'has-error': hasErrors() },
										{ 'has-icon': saving },
										{ 'is-saving': { saving } }
									) }
									type="submit"
									text={
										saving
											? __( 'Saving…', 'quotes-dlx' )
											: __( 'Save Defaults', 'quotes-dlx' )
									}
									icon={ saving ? Spinner : false }
									iconSize="18"
									iconPosition="right"
									disabled={ saving || resetting }
								/>
								<Button
									className={ classNames(
										'qdlx__btn qdlx__btn-danger qdlx__btn--icon-right',
										{ 'has-icon': resetting },
										{ 'is-resetting': { resetting } }
									) }
									type="button"
									text={
										resetting
											? __( 'Resetting…', 'quotes-dlx' )
											: __( 'Reset Defaults', 'quotes-dlx' )
									}
									icon={ resetting ? Spinner : false }
									iconSize="18"
									iconPosition="right"
									disabled={ saving || resetting }
									onClick={ ( e ) => {
										setResetting( true );
										handleReset( e );
									} }
								/>
							</div>
							{ hasErrors() && (
								<Notice
									message={ __(
										'There are form validation errors. Please correct them above.'
									) }
									status="error"
									politeness="polite"
								/>
							) }
							{ isSaved && (
								<Notice
									message={ __( 'Your settings have been saved.' ) }
									status="success"
									politeness="assertive"
								/>
							) }
							{ isReset && (
								<Notice
									message={ __( 'Your settings have been reset to defaults.' ) }
									status="success"
									politeness="assertive"
								/>
							) }
						</div>
					</div>
				</form>
			</div>
		</>
	);
};

export default AdminAdvanced;
